#!/usr/bin/env bash
# MEDfl client setup for the site "{{.SiteID}}", generated by MEDomics on {{.GeneratedAt}}.
#
# Run it once on the client machine:   sudo bash {{.FileName}}
#
# It joins the study Tailscale network, installs the MEDfl agent in ~/medfl and starts it now and at every boot.
# It contains the join key and the study token of this site: do not share it with other sites.
set -euo pipefail

SITE_ID="{{.SiteID}}"
COORDINATOR="{{.CoordinatorIP}}"
PORT="{{.Port}}"
AUTH_KEY="{{.AuthKey}}"
TOKEN="{{.Token}}"

info() { echo "[MEDfl] $*"; }
fail() { echo "[MEDfl] ERROR: $*" >&2; exit 1; }

[ "$(id -u)" -eq 0 ] || fail "run this script with sudo: sudo bash $0"
RUN_USER="${SUDO_USER:-root}"
RUN_HOME="$(getent passwd "$RUN_USER" | cut -d: -f6)"
BASE="$RUN_HOME/medfl"

# ---------- 1. System packages ----------
if command -v apt-get >/dev/null 2>&1; then
  info "Installing the system packages (curl, Python)..."
  apt-get update -qq
  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq curl python3 python3-venv python3-pip >/dev/null
fi
command -v curl >/dev/null 2>&1 || fail "curl is required: install it, then run this script again"

# ---------- 2. Tailscale ----------
if ! command -v tailscale >/dev/null 2>&1; then
  info "Installing Tailscale..."
  curl -fsSL https://tailscale.com/install.sh | sh
fi
if tailscale status >/dev/null 2>&1; then
  info "Tailscale is already connected."
elif [ -n "$AUTH_KEY" ]; then
  info "Joining the study network..."
  tailscale up --authkey "$AUTH_KEY" --hostname "$SITE_ID" || fail "tailscale up failed: the join key may be used or expired, ask the coordinator for a new script"
else
  info "Sign in to the study network with the link below (accept the coordinator's invitation first)."
  tailscale up --hostname "$SITE_ID"
fi

# ---------- 3. Python 3.10 to 3.12 ----------
PYTHON=""
for cand in python3.12 python3.11 python3.10 python3; do
  if command -v "$cand" >/dev/null 2>&1 && "$cand" -c 'import sys; sys.exit(0 if (3, 10) <= sys.version_info[:2] <= (3, 12) else 1)'; then
    PYTHON="$(command -v "$cand")"
    break
  fi
done
[ -n "$PYTHON" ] || fail "Python 3.10, 3.11 or 3.12 is required: install it, then run this script again"
if ! "$PYTHON" -c 'import ensurepip' >/dev/null 2>&1 && command -v apt-get >/dev/null 2>&1; then
  PY_VERSION="$("$PYTHON" -c 'import sys; print("%d.%d" % sys.version_info[:2])')"
  DEBIAN_FRONTEND=noninteractive apt-get install -y -qq "python$PY_VERSION-venv" >/dev/null || true
fi
"$PYTHON" -c 'import ensurepip' >/dev/null 2>&1 || fail "the Python venv module is missing: install python3-venv, then run this script again"
info "Using $PYTHON"

# ---------- 4. Agent ----------
install -d -o "$RUN_USER" -m 755 "$BASE" "$BASE/data" "$BASE/logs"
info "Downloading the MEDfl agent from the coordinator ($COORDINATOR)..."
for i in $(seq 1 30); do
  if curl -fsS "http://$COORDINATOR:$PORT/medfl/agent/medfl_agent.py" -o "$BASE/medfl_agent.py"; then
    break
  fi
  [ "$i" -eq 30 ] && fail "cannot reach the coordinator at $COORDINATOR:$PORT: check that MEDomics is open on the coordinator and that this machine is in the study network"
  sleep 2
done
cat >"$BASE/medfl_agent.json" <<EOF
{
  "ctrl_url": "ws://$COORDINATOR:$PORT/medfl/rw/ws/agent",
  "agent_id": "$SITE_ID",
  "base_dir": "$BASE",
  "token": "$TOKEN"
}
EOF
chown "$RUN_USER" "$BASE/medfl_agent.py" "$BASE/medfl_agent.json"
chmod 600 "$BASE/medfl_agent.json"

# ---------- 5. Service ----------
SERVICE="medfl-agent-$SITE_ID"
if command -v systemctl >/dev/null 2>&1 && [ -d /run/systemd/system ]; then
  cat >"/etc/systemd/system/$SERVICE.service" <<EOF
[Unit]
Description=MEDfl agent ($SITE_ID)
After=network-online.target tailscaled.service
Wants=network-online.target

[Service]
User=$RUN_USER
Environment=HOME=$RUN_HOME
WorkingDirectory=$BASE
ExecStart=$PYTHON $BASE/medfl_agent.py
Restart=always
RestartSec=10

[Install]
WantedBy=multi-user.target
EOF
  systemctl daemon-reload
  systemctl enable "$SERVICE" >/dev/null
  systemctl restart "$SERVICE"
  info "The agent runs as the service $SERVICE (systemctl status $SERVICE)."
else
  info "systemd was not found: start the agent yourself with: $PYTHON $BASE/medfl_agent.py"
fi

info "Done."
info "Put the site's files in $BASE/data: dataset.csv (training) and, for the holdout test, holdout.csv."
info "The first start installs MEDfl (10 to 20 minutes). Follow it with: tail -f $BASE/logs/agent.log"
